import{_ as i,l as s,o as e,c as o,v as t,p as n,x as l,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"防火墙与状态","description":"","frontmatter":{"title":"防火墙与状态","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/firewall-state.md","filePath":"cs/firewall-state.md","lastUpdated":1789023840000}'),h={name:"cs/firewall-state.md"};function A(E,a,_,T,f,u){const r=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="防火墙与状态" tabindex="-1">防火墙与状态 <a class="header-anchor" href="#防火墙与状态" aria-label="Permalink to &quot;防火墙与状态&quot;">​</a></h1><div class="epigraph"><p>边界按策略允许或拒绝分组；有状态的那一层记得「这是已允许会话的回复」，而不是每一包单独看端口号。</p><footer>—— 据 Cheswick, Bellovin and Rubin；Stallings 对分组过滤与状态检测的整理</footer></div><p><a href="/cs/tls13-0rtt">上一课</a>把应用数据收进 AEAD。本课不重做 ClientHello。缺口是：网络边界仍要执行访问控制，但载荷已不可读。防火墙在 IP/端口/状态上落实最小特权：默认拒绝，只允许声明过的五元组与回程。这是<a href="/cs/acl-least-priv">ACL</a>在分组上的投影，不是另一种密码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无状态过滤只看单包的地址与端口，无法区分「新连接」与「已建立的回程」，也难处理动态端口。缺口不是再讲<a href="/cs/ip-subnet">IP 编址</a>，而是连接跟踪：记下 TCP 状态或超时的 UDP 流，只让匹配的回包通过。TLS 之后，第七层 HTTP 规则除非终止 TLS，否则看不见路径。</p><p><span class="marginnote">状态表本身是资源：表满则可用失败（CIA 的 A），也是后课放大攻击的一种打点。默认拒绝比默认允许更符合 Saltzer 的失败安全。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>策略：入站/出站、源与目的、协议、端口、已建立。状态检测维护流表。NAT 常与状态表绑在一起（<a href="/cs/dhcp-nat">DHCP 与 NAT</a>已有地址翻译）。本课不把下一代 DPI 产品当理论：加密提高 DPI 的代价，策略应假设看不见明文。</p>',8)),(e(),n(c,null,{default:l(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PKT%5B%22%E5%88%86%E7%BB%84%22%5D%20--%3E%20ACL%5B%22%E6%97%A0%E7%8A%B6%E6%80%81%E8%A7%84%E5%88%99%22%5D%0A%20%20PKT%20--%3E%20ST%5B%22%E6%B5%81%E8%A1%A8%E7%8A%B6%E6%80%81%22%5D%0A%20%20ST%20--%3E%20DEC%5B%22%E6%94%BE%E8%A1%8C%20%2F%20%E4%B8%A2%E5%BC%83%22%5D%0A%20%20DEC%20--%3E%20MITM%5B%22%E5%90%8E%E8%AF%BE%3A%20%E4%B8%AD%E9%97%B4%E4%BA%BA%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>防火墙缩小攻击面：未声明的入站服务根本到不了套接字。它不认证对端是谁——那是 TLS 与应用。状态表使回复合法，也使伪造「已建立」成为另一类威胁（需序列号等到 TCP 课已有的难度）。与沙箱对照：一个在主机进程，一个在网络边界，矩阵的客体分别是系统调用与分组。</p><p>无状态规则挡不住「已建立」伪造到何种程度，取决于是否跟踪序列与超时。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>防火墙不是杀毒，也不修溢出。加密隧道可以从允许的端口把任意应用带出去（策略泄漏）。本课不教如何躲过防火墙。中间人若位于防火墙终止 TLS 之处，身份模型完全改变——下一课。</p><p>出站默认允许、入站默认拒绝是常见折中：内部主机仍可能被当跳板。最小特权要求出站也收敛。后课默认：边界可以有状态 ACL；主动者若插在链路上，要靠认证而不是靠「端口开了」。</p><p>策略是访问控制，状态表是实现。表的超时必须大于合法往返、小于资源耗尽窗口，这是可用与正确的折中。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>默认拒绝加显式允许，是最小特权在分组上的投影。</p></li><li><p>后课中间人是认证几何，不是再加一条端口规则能关的。</p></li><li><p>TLS 藏载荷；防火墙用五元组与流表做最小特权。</p></li><li><p>状态表服务回程，也消耗内存（可用轴）。</p></li><li><p>主动插入链路冒充端点，是中间人课。</p></li><li><p>出处：Cheswick, Bellovin and Rubin；Stallings；Saltzer and Schroeder 原则。</p></li></ul>',9))])}const P=i(h,[["render",A]]);export{B as __pageData,P as default};
